  jsonb_build_array(
    jsonb_build_object('kind','fixed','scope','site','min_rank',1,'text','Билеты классу: в билетах по таджикскому и английскому языкам ответ на открытый вопрос вводится в 5 клеток, как на бланке, — раньше клеток было 4, и ответ из пяти цифр ввести было нельзя.'),
    jsonb_build_object('kind','fixed','scope','site','min_rank',1,'text','Банк вопросов: у 9 открытых вопросов по математике и физике изменены числа в условии, а 14 задач по математике с дробным ответом убраны в корзину — теперь ответ каждого открытого вопроса — целое число без минуса и дробей, которое помещается в клетки бланка.')
  ),
  '2026-11-24 19:00:00+05');
